"use strict";

// OpenClaw Hook：usage-query
// 用途：教練在 Telegram 說「流量」時，自動注入 AI 流量數據到 context。
// 事件：message:preprocessed
// 注入：event.context.inject.push({ role:'system', content })
// 資料來源：~/.openclaw/workspace/state/usage_cache.json（由軍師或 cron 更新）
// 軍師建立 2026-06-06

const fs = require('fs');
const path = require('path');

const CACHE_FILE = path.join(process.env.HOME, '.openclaw', 'workspace', 'state', 'usage_cache.json');

function extractText(event) {
  const c = (event && event.context) || {};
  const cands = [
    event.text,
    c.text, c.content, c.prompt, c.input, c.transcript, c.userText, c.body, c.userMessage,
    (c.message && (typeof c.message === 'string' ? c.message : (c.message.text || c.message.content))),
  ];
  const pickLast = (arr) => {
    if (Array.isArray(arr) && arr.length) {
      const last = arr[arr.length - 1];
      if (typeof last === 'string') return last;
      if (last && typeof last === 'object') return last.text || last.content || '';
    }
    return '';
  };
  cands.push(pickLast(event.messages));
  cands.push(pickLast(c.messages));
  for (const v of cands) if (typeof v === 'string' && v.trim()) return v;
  return '';
}

function shouldTrigger(text) {
  if (!text) return { trigger: false };
  const t = text.trim();
  // 「流量」= 預設查 Claude
  // 「流量 open go」「流量 opencode」= 查 OpenCode Go
  // 「流量 全部」= 查全部
  if (/流量/i.test(t)) {
    if (/open\s*(?:code)?\s*go|opencode/i.test(t)) return { trigger: true, target: 'opencode' };
    if (/全部|所有|all/i.test(t)) return { trigger: true, target: 'all' };
    if (/minimax/i.test(t)) return { trigger: true, target: 'minimax' };
    return { trigger: true, target: 'claude' };
  }
  return { trigger: false };
}

function formatClaude(d) {
  if (!d) return '（無 Claude 數據）';
  return [
    `📊 Claude（${d.plan}）流量報告`,
    `當前 session：已用 ${d.session_used}（${d.session_reset}後重置）`,
    `每週用量：已用 ${d.weekly_used}（${d.weekly_reset}重置）`,
    `額外額度：已花 ${d.credits_spent} / 上限 ${d.credits_limit}（${d.credits_reset}重置）`,
    `餘額：${d.balance}`,
  ].join('\n');
}

function formatOpenCode(d) {
  if (!d) return '（無 OpenCode Go 數據）';
  return [
    `📊 OpenCode Go 流量報告`,
    `滾動使用量：${d.rolling_used}（${d.rolling_reset}後重置）`,
    `每週使用量：${d.weekly_used}（${d.weekly_reset}後重置）`,
    `每月使用量：${d.monthly_used}（${d.monthly_reset}後重置）`,
  ].join('\n');
}

function formatMiniMax(d) {
  if (!d) return '（無 MiniMax 數據）';
  return [
    `📊 MiniMax 流量報告`,
    `昨日 token：${d.yesterday_tokens}`,
    `近 7 天：${d.last_7_days}`,
    `近 30 天：${d.last_30_days}`,
    `歷史總計：${d.total}`,
  ].join('\n');
}

module.exports = function (event) {
  try {
    const text = extractText(event);
    const { trigger, target } = shouldTrigger(text);
    if (!trigger) return;

    if (!fs.existsSync(CACHE_FILE)) {
      const inject = event.context.inject || (event.context.inject = []);
      inject.push({ role: 'system', content: '⚠️ 流量快取檔案不存在，請通知軍師更新流量數據。' });
      return;
    }

    const cache = JSON.parse(fs.readFileSync(CACHE_FILE, 'utf-8'));
    const updated = cache.updated || '未知';

    let report = '';
    if (target === 'claude') {
      report = formatClaude(cache.claude);
    } else if (target === 'opencode') {
      report = formatOpenCode(cache.opencode_go);
    } else if (target === 'minimax') {
      report = formatMiniMax(cache.minimax);
    } else {
      report = [formatClaude(cache.claude), '', formatOpenCode(cache.opencode_go), '', formatMiniMax(cache.minimax)].join('\n');
    }

    report += `\n\n🕐 數據更新時間：${updated}`;

    const inject = event.context.inject || (event.context.inject = []);
    inject.push({
      role: 'system',
      content: `📊 流量查詢結果（系統自動注入）\n\n${report}\n\n請用白話文把以上數據回報給教練，不要加任何技術用語。`
    });
  } catch (e) {
    // silent fail
  }
};

